{"question_id": "qst_0001", "question_type": "basic", "source_types": ["github"], "question": "What are the default size limits for file uploads and total request size for the new multipart upload support on the OpenAI-compatible API endpoints?", "expected_doc_ids": ["dsid_ae068ee4aa9640159427cd941bef0238"], "gold_answer": "The default limits are 10 MiB per file (max_file_size) and 50 MiB total per request (max_total_request_size) for multipart uploads on the OpenAI-compatible endpoints.", "answer_facts": ["The default per file upload size limit (max_file_size) for multipart uploads on OpenAI-compatible endpoints is 10 MiB.", "The default total request size limit (max_total_request_size) for multipart uploads on OpenAI-compatible endpoints is 50 MiB."]}
{"question_id": "qst_0002", "question_type": "basic", "source_types": ["github"], "question": "What is the name of the new metric added so SRE can track when server-side streaming sessions get finalized due to hitting the time limit?", "expected_doc_ids": ["dsid_9550250a59e74f1bbd5612480b2e7100"], "gold_answer": "The new metric is `stream.timebox_finalized` (with labels for route and model).", "answer_facts": ["The new metric added is named stream.timebox_finalized", "The metric stream.timebox_finalized includes labels for route and model"]}
